const nodemailer = require('nodemailer');

const SMTP_CONFIG = {
  host: 'smtp.gmail.com',
  port: 587,
  secure: false,
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS,
  }
};

const FELADÓ = '"Keszisi Sí & Kerékpár Szerviz" <dunakeszisi@gmail.com>';

function createTransporter() {
  return nodemailer.createTransport(SMTP_CONFIG);
}

const SKILL_LABELS = {
  elso_sielo: 'Első síelő',
  kezdo: 'Kezdő',
  kozephalado: 'Középhaladó',
  halado: 'Haladó',
  profi: 'Profi'
};

function formatDate(d) {
  if (!d) return '—';
  const [y, m, day] = d.split('-');
  return `${y}. ${m}. ${day}.`;
}

// Keszisi valódi logó (webp, base64 kódolva az emailhez)
