function buildEmailText(booking) {
  const { contact_name, booking_id, pickup_date, return_date, renters } = booking;
  return [
    `Keszisi Sí & Kerékpár Szerviz`,
    `Felszerelés beállítási adatok és nyilatkozatok visszaigazolása — #${booking_id}`,
    ``,
    `Kedves ${contact_name}!`,
    ``,
    `Ez a levél visszaigazolja, hogy felszerelés beállítási adatai és nyilatkozatai`,
    `sikeresen rögzítésre kerültek.`,
    ``,
    `Tervezett átvétel: ${formatDate(pickup_date)}`,
    `Tervezett visszahozatal: ${formatDate(return_date)}`,
    ``,
    `Rögzített személyek:`,
    ...renters.map((r, i) =>
      `${i+1}. ${r.name} | ${r.age} év | ${r.height_cm}cm | ${r.weight_kg}kg | EU${r.shoe_size} | ${SKILL_LABELS[r.skill_level]} | DIN: ${Number(r.din_value).toFixed(2)}`
    ),
    ``,
    `Elfogadott nyilatkozatok:`,
    `✓ Adatkezelési tájékoztató — megismertem és elfogadtam`,
    `✓ Felelősségi nyilatkozat — megismertem és tudomásul vettem`,
    ``,
    `Kérjük, jelezze munkatársainknak az üzletben, hogy az előzetes adatmegadást elvégezte.`,
    ``,
    `---`,
    `Keszisi Sí & Kerékpár Szerviz`,
    `2120 Dunakeszi, Katona József u. 23.`,
    `+36 30 459 5670 | dunakeszisi@gmail.com | keszisi.hu`,
  ].join('\n');
}

async function sendConfirmationEmail(booking) {
  const transporter = createTransporter();
  await transporter.verify();
  const info = await transporter.sendMail({
    from: FELADÓ,
    to: booking.contact_email,
    subject: `✓ Adatok rögzítve — Keszisi Sí & Kerékpár Szerviz (#${booking.booking_id})`,
    text: buildEmailText(booking),
    html: buildEmailHTML(booking),
  });
  console.log(`📧 Email elküldve: ${booking.contact_email} (${info.messageId})`);
  return info;
}

